#!/usr/bin/env python3
"""Six actual production captures, source links and measured gameplay stopping rigs."""
import base64,hashlib,html,json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
read=lambda p:json.loads((R/p).read_text());sha=lambda p:hashlib.sha256((R/p).read_bytes()).hexdigest();esc=lambda s:html.escape(str(s),quote=True)
version=read('package.json')['version'];captures=read('artifacts/expansion-captures/cameras.json');cards=[];manifest=[]
notes={
'yas-hotel':('ae-2009','Twin hotel wings from mapped building-part outlines, original domed lattice/glass bands, raised connecting walkway and approximate marina water.','Shell spacing/height, lattice and water boundary remain approximate; architecture is not scanned. Pit tunnel elevation/portals are simplified.'),
'yas-marsa':('ae-2009','The post-2021 sweeping Marsa T9, 5% authored camber, red/white kerbs, turquoise margins, selective outer asphalt and event viewing stands.','Constant 14 m playable road does not reproduce the real variable widths. Apron boundaries and safety-wall positions are estimates.'),
'zandvoort-hugenholtz':('nl-1948','Banked Hugenholtz T3, green inside edging, outside gravel, dune-coloured terrain and safety fencing. The same cross-slope supports the four tyres and rolls the car.','Smooth 18° linear cross-slope estimate, not the real variable bowl or calibrated 3D banked-corner tyre dynamics. Raised apron edges use simplified earth retaining faces instead of a surveyed dune transition.'),
'zandvoort-luyendyk':('nl-1948','Banked final Arie Luyendyk corner feeds the mapped main straight; actual geographic dune context, red/white kerbs, gravel and mapped/photo-guided facilities.','Modern 2020 layout is shared by every car. Terrain is filtered GLO-30 DSM, not a road survey; stand dimensions/materials remain simplified.'),
'baku-castle':('az-2016','Mapped Old City wall with original crenellations/turret, a narrow rising corner sequence, pale urban facades and fenced concrete/Armco corridor.','Baku uses 90 m DEM where 30 m public data is unavailable. Wall dimensions and turret detail are photo-guided estimates; constant 8 m road is not a variable-width street survey.'),
'baku-waterfront':('az-2016','Long mapped shoreline straight, government-area mapped building footprints, race furniture and approximate Caspian context traced from retained satellite imagery.','Real straights are wider than the constant 8 m playable road. Exact temporary grandstand/garage facades, sponsor inventory and shoreline details are not reconstructed.')}
for c in captures:
 assert c['version']==version
 id=c['id'];kind,change,limit=notes[id];p=f'artifacts/expansion-captures/{id}.jpg';blob=(R/p).read_bytes();uri='data:image/jpeg;base64,'+base64.b64encode(blob).decode()
 cards.append(f'<article data-kind="{kind}" id="{id}"><header><small>ACTUAL GAME CAPTURE / {esc(version)}</small><h2>{esc(c["title"])}</h2></header><img src="{uri}" width="1000" height="625" alt="Actual production render: {esc(c["title"])}"><div class="details"><p><b>IMPLEMENTED</b>{esc(change)}</p><p><b>REMAINING LIMITS</b>{esc(limit)}</p></div></article>')
 manifest.append({**c,'sha256':hashlib.sha256(blob).hexdigest(),'bytes':len(blob)})
inputs=['data/tracks.json','data/imagery.json','data/buildings.json','data/pit-lanes.json','data/corner-details.json','data/reference-scenes.json','data/expansion-references.json','web/graphics.js','web/road-surface.js','web/reference-scene.js','src/braking.rs','src/lib.rs','src/corner.rs','src/elevation.rs','src/surface_mesh.rs','web/wasm/apex_bg.wasm']
(R/'data/expansion-captures.json').write_text(json.dumps(dict(version=version,inputs={p:sha(p)for p in inputs},captures=manifest),indent=2)+'\n')
style='''*{box-sizing:border-box}body{margin:0;background:#101b22;color:#e8ede9;font:15px/1.75 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:30px 24px 70px}nav{display:flex;justify-content:space-between;border-bottom:1px solid #3d5159;padding-bottom:20px;font-size:10px;letter-spacing:.15em}h1{font-size:clamp(42px,7vw,78px);letter-spacing:-.055em;line-height:1.08;margin:48px 0 24px}h1 span{color:#75c8c4}.lead{max-width:900px;color:#b4c5cb}.scope,.brakes{border:1px solid #40535d;padding:22px;margin:28px 0;background:#182931;border-left:4px solid #75c8c4}.brakes{border-left-color:#dec295}.brakes h2{font-size:24px;margin:0 0 14px}.brakes p,.scope{font-size:13px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:9px 12px;text-align:left;border-bottom:1px solid #40535d}th{color:#dec295}button{border:1px solid #45666d;border-radius:25px;background:#1a303a;color:#dce9e8;font:inherit;font-size:12px;padding:8px 18px;cursor:pointer}button[aria-pressed=true]{background:#75c8c4;color:#10252d}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:30px 0}article{background:#18282f;border:1px solid #3b525a;border-radius:10px;overflow:hidden;margin:0 0 32px}header{padding:20px 24px}small{font-size:10px;color:#84c7c3;letter-spacing:.1em}h2{font-size:28px;letter-spacing:-.03em;line-height:1.3;margin:8px 0}img{display:block;width:100%;height:auto}.details{display:grid;grid-template-columns:1fr 1fr;gap:28px;padding:20px 24px 26px}.details p{font-size:13px;color:#bfcfd0;margin:0}.details b{display:block;font-size:10px;letter-spacing:.1em;color:#80c8c0;margin-bottom:6px}.details p:last-child b{color:#d5bc92}a{color:#82cec7}.notes{font-size:12px;color:#a9bec3}.hidden{display:none}@media(max-width:650px){main{padding:24px 14px}.details{grid-template-columns:1fr;gap:18px}header,.details{padding:18px}nav{font-size:9px}td,th{padding:8px 5px}.scope,.brakes{padding:16px}}'''
rows=''.join(f'<tr><td>{year}</td><td>{d} m</td><td>{t} s</td></tr>'for year,d,t in [('1967','32.48','2.37'),('1988','23.98','1.78'),('2004','20.32','1.52'),('2023','18.85','1.41'),('2021','18.53','1.38')])
refs=read('data/expansion-references.json');links=''.join(f'<li><a href="{esc(p["page"])}">{esc(p["track"])} · {esc(p["subject"])}</a> — {esc(p["observation"])}</li>'for p in refs['photos']);links+=''.join(f'<li><a href="{esc(p["url"])}">Engineering / circuit account · {esc(p["track"])}</a> — {esc(p["observations"])}</li>'for p in refs['engineering_sources'])
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APEX / HERITAGE — Three circuits. Brakes that bite.</title><style>{style}</style></head><body><main><nav><b>APEX / HERITAGE</b><span>DRIVING UPDATE · {version}</span></nav><h1>Three new circuits.<br><span>Brakes that bite.</span></h1><p class="lead">Abu Dhabi, Zandvoort and Baku: mapped modern layouts, photographic research and original shared scenery. Six real production captures below—not concept art, AI-generated venue images or a claim of surveyed accuracy.</p><section class="brakes"><h2>Brake priority, not pedal cancellation.</h2><p>Full braking now suppresses engine thrust even if the accelerator remains held. Brake force no longer dwindles to 20% at the cornering limit: braking keeps its force without cutting the steering budget. Combined-input rear slip is still modelled; this is not a strict friction-circle simulation. Aero-supported load improves high-speed braking. Half-pedal and wet-road stops remain progressively longer.</p><table><thead><tr><th>CAR ERA</th><th>100–0 km/h · GAME</th><th>TIME · GAME</th></tr></thead><tbody>{rows}</tbody></table><p>Measured shared Rust simulation rigs: default team, fresh dry tyres, assists on, 120 Hz, fixed Monza start station. Position reset isolates braking from collisions/runoff while holding the same road grade. These are <strong>gameplay measurements, not real-car telemetry or certified stopping distances</strong>. Full accelerator plus full brake produces the same stop as full brake alone. Old lap records remain stored but use a fresh handling namespace.</p></section><div class="scope"><b>Scope:</b> modern layouts for all five car eras, explicitly labelled substitutes. Existing ten circuit/layout/surface records remain unchanged. New Zandvoort banking is part of the road/kerb geometry and wheel support, not a visual-only tilted backdrop. No stock-photo pixels are redistributed.</div><div class="filters"><button data-kind="all" aria-pressed="true">All six views</button><button data-kind="ae-2009" aria-pressed="false">Abu Dhabi</button><button data-kind="nl-1948" aria-pressed="false">Zandvoort</button><button data-kind="az-2016" aria-pressed="false">Baku</button></div>{''.join(cards)}<section class="notes"><h2>What the references establish.</h2><ul>{links}</ul><p>Map lines: Tomislav Bacinger, MIT. Buildings/pits/wall outlines: © OpenStreetMap contributors, ODbL 1.0. Elevation: Copernicus GLO-30 / GLO-90 DSM, filtered and approximate. Satellite context: modified Copernicus Sentinel data 2025. Individual photo dates/rights vary; thumbnails are reference-only and are not embedded here. The source repository retains exact source URLs, map snapshots, licenses, photo-preview hashes and capture inputs in the expansion manifests.</p><p><a href="https://the-crab-post-office.github.io/apex-heritage/">Play ↗</a> · <a href="https://github.com/the-crab-post-office/apex-heritage">Source / license notices ↗</a></p></section></main><script>for(const button of document.querySelectorAll('button[data-kind]'))button.onclick=()=>{{for(const b of document.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b===button));for(const card of document.querySelectorAll('article'))card.classList.toggle('hidden',button.dataset.kind!=='all'&&card.dataset.kind!==button.dataset.kind);}};</script></body></html>'''
(R/'web/public/new-circuits.html').write_text(page);print('Built new-circuits.html:',len(page.encode()),'bytes; six actual game views')
